  "gram-236": {"promptNative":"Umas vinte pessoas. (Que palavra significa 'aproximadamente' antes do classificador?)"},
  "gram-237": {"promptNative":"Tem olhos grandes e redondos. (Que forma reduplicada do adjetivo corresponde?)"},
  "gram-238": {"promptNative":"Deixou impecável. (Qual é a reduplicação AABB correta?)"},
  "gram-239": {"promptNative":"Deixa eu pensar. (Que forma V一V suaviza 'pensar'?)"},
  "gram-240": {"promptNative":"Cada estudante tem um número. (Que palavra significa 'cada / todos', combina com 都?)"},
  "gram-241": {"promptNative":"Bom dia, pessoal! (Que sufixo pluraliza 'colegas'?)"},
  "gram-242": {"promptNative":"O livro que comprei é meu. (Que forma de oração relativa + 的 corresponde?)"},
  "gram-243": {"promptNative":"Um dos escritores mais famosos. (Que expressão significa 'um dos'?)"},
  "gram-244": {"promptNative":"Sejam todos bem-vindos! (Que palavra é o formal 'cada um / todos', como em 各位?)"},
  "gram-245": {"promptNative":"Isto é tudo o que sei. (Que palavra literária corresponde a 我__知道的?)"},
  "gram-246": {"promptNative":"Seu espírito nos comoveu. (Qual é a estrutura passiva literária?)"},
  "gram-247": {"promptNative":"Ele quebrou meu telefone. (Que estrutura acrescenta o 给 coloquial a uma frase com 把?)"},
  "gram-248": {"promptNative":"Prefere sair perdendo a incomodar os outros. (Que par significa 'preferir…a'?)"},
  "trad-0": {"prompt":"Traduzir: 'Parabéns!'","promptNative":"Traduzir: 'Parabéns!'"},
  "trad-1": {"prompt":"Traduzir: 'Vá com Deus. (a alguém que está de partida)'","promptNative":"Traduzir: 'Vá com Deus. (a alguém que está de partida)'"},
